base=u10.base
R=Path(__file__).resolve().parents[2];C1=R/'reading/french/c1/passages.jsonl';B2=R/'reading/french/b2/passages.jsonl';SCHEMA=R/'reading/schema/passage.schema.json';LOCK=R/'reading/audit/french_c1_unit09_frontier_lock.json';PLAN=R/'reading/audit/french_c1_unit10_plan.json';SEL=R/'reading/audit/french_c1_unit10_target_selection.json';PAIR='fr-c1-u10-response-resilience-viewpoints'
USE={'exactement':'« Exactement » exige ici une correspondance précise entre l’affirmation et ce que les données permettent réellement d’établir; la précision verbale ne doit pas dépasser la précision de la preuve.','autant':'« Autant » introduit une comparaison d’ampleur qui doit conserver la même unité, la même période et la même population pour être interprétable.','propre':'« Propre » distingue ce qui appartient spécifiquement à un mécanisme ou à un cas de ce qui est partagé avec d’autres situations.','sorte':'Une « sorte » de phénomène constitue une catégorie provisoire; la synthèse doit expliquer quels critères rendent deux cas suffisamment semblables pour être regroupés.',
'importer':'« Importer » signifie ici compter pour la décision : une variable peut être statistiquement visible sans modifier l’action, ou au contraire être décisive malgré une estimation encore imprécise.','marcher':'« Marcher » signifie fonctionner dans un contexte donné; une solution qui marche localement doit encore être testée lorsqu’on change d’échelle, de population ou de contrainte.','tirer':'« Tirer » une conclusion d’un ensemble de sources décrit le passage de l’observation à l’inférence; le texte demande quelles prémisses rendent ce passage légitime.','facile':'« Facile » est traité comme une propriété relative à des ressources, compétences et contraintes; la synthèse évite d’en faire une qualité universelle de la solution.',
'défense':'La « défense » désigne une justification structurée d’une position ou d’une personne; elle doit être reconstruite dans sa forme la plus forte avant d’être évaluée.','secours':'Le « secours » représente une intervention destinée à réduire un dommage immédiat; son urgence ne supprime pas la nécessité d’examiner effets secondaires et conditions de sortie.','procès':'Le « procès » fournit un exemple institutionnel où plusieurs récits, preuves et normes sont organisés dans une procédure contradictoire; le passage reste juridiquement fictif.','criminel':'« Criminel » est une qualification lourde qui ne doit jamais servir de simple intensificateur; elle exige un cadre, des faits et une procédure appropriés dans le cas fictif.',
'briser':'« Briser » décrit une rupture de capacité ou de relation; une analyse systémique distingue le point de rupture de la chaîne de causes qui l’a rendu possible.','exploser':'« Exploser » représente une augmentation ou rupture soudaine; le texte vérifie si la métaphore correspond à une variation mesurée ou seulement à un effet rhétorique.','terrible':'« Terrible » exprime une évaluation forte; la synthèse la décompose en gravité, fréquence, distribution et réversibilité des conséquences.','nul':'« Nul » est un jugement global et familier que l’analyse refuse comme conclusion suffisante; elle exige des critères qui montrent précisément ce qui échoue.',
'docteur':'Le « docteur » sert d’exemple de professionnel disposant d’une expertise située; le titre ne rend pas toute affirmation experte dans tous les domaines.','étudier':'« Étudier » signifie examiner systématiquement une question avec des méthodes adaptées; le passage distingue étude, observation occasionnelle et décision pratique.','inquiéter':'« Inquiéter » décrit un signal d’attention ou une réaction; la préoccupation peut motiver une enquête sans constituer elle-même une preuve du mécanisme redouté.','sérieusement':'« Sérieusement » marque ici le degré d’attention accordé à une hypothèse; prendre un risque au sérieux signifie le tester proportionnellement à sa plausibilité et à sa gravité, non le présumer certain.'}
EXTRA=["La synthèse C1 ne cherche pas à tout réduire à une seule métrique. Elle construit une architecture d’arguments : faits relativement solides, inférences conditionnelles, valeurs ou seuils décisionnels, meilleur contreargument et règle de révision. Cette structure permet de comparer des domaines différents sans prétendre qu’ils sont identiques.","Une source ou un expert est utilisé selon son accès réel à l’information. L’autorité institutionnelle, l’expérience vécue et la compétence technique peuvent chacune être pertinentes, mais elles soutiennent des types d’affirmations différents. Le dossier rend cette correspondance explicite.","Le transfert entre contextes exige un test de mécanisme. Une solution qui réussit dans un cas n’est pas exportée par simple analogie; l’analyse vérifie quelles conditions causales sont partagées et lesquelles changent suffisamment pour modifier l’effet attendu.","Le contreargument le plus fort reçoit une conséquence opérationnelle. S’il était correct, quel indicateur devrait changer, quelle recommandation deviendrait moins défendable et quelle nouvelle information permettrait de trancher ? Cette discipline empêche l’objection d’être seulement décorative.","Enfin, la recommandation sépare décision actuelle et certitude finale. Il est souvent rationnel d’agir avec une information incomplète si l’action est proportionnée, réversible et accompagnée d’un plan d’apprentissage; l’incertitude devient alors une propriété gérée plutôt qu’un prétexte à l’inaction ou à la confiance excessive."]
def h(p):return subprocess.check_output(['git','hash-object',str(p)],text=True).strip()
def fit(ps,lo,hi):
 p=list(ps);t='\n\n'.join(p);i=0
 while len(t.split())<lo and i<len(EXTRA):p[-1]+=' '+EXTRA[i];i+=1;t='\n\n'.join(p)
 if not lo<=len(t.split())<=hi:raise AssertionError(f'Unit10 word band {len(t.split())} not {lo}-{hi}')
 return p,t
def bridge(fs):return 'Révision historiographique : '+', '.join(f'« {x} »' for x in fs)+'. Ces formes rappellent que toute synthèse dépend aussi de temporalité, provenance et perspective.'
def qs(s,forms):
 typ='cross_text_synthesis' if s.get('pair') and s['id'].endswith('p04') else 'summary';pr='Compare les deux perspectives : quel compromis institutionnel les rapproche ?' if typ=='cross_text_synthesis' else 'Résume la logique de synthèse.';an=s.get('across',s['asummary'])
 return [('main_claim',s['qclaim'],s['aclaim'],[forms[0]]),('inference',s['qinfer'],s['ainfer'],[forms[1]]),('assumption',s['qassume'],s['aassume'],[forms[2]]),('argument_relation',s['qrelation'],s['arelation'],[forms[3]]),('stance','Quelle position de synthèse l’auteur adopte-t-il ?',s['astance'],[forms[0],forms[3]]),(typ,pr,an,[forms[1],forms[2]])]+[('vocabulary_in_context',f'Quel rôle joue « {f} » dans la synthèse ?',USE[f],[f]) for f in forms]
def mk(s,forms,reviews,prior,deck,lo,hi,theme):
 ps=list(s['paras']);ps[1]+=' '+' '.join(USE[f] for f in forms);ps[2]+=' '+bridge(reviews);ps,text=fit(ps,lo,hi);P=base.prior(prior);new=[base.nt(f,text,deck) for f in forms];rev=[base.rev(f,P) for f in reviews];ids={t['form']:t['id'] for t in new+rev};q,a=base.qa(qs(s,forms),ids)
 return {'id':s['id'],'language':'fr','cefr':'C1','unit':10,'sequence':s['seq'],'revision':1,'title':s['title'],'passage_type':'integration','genre':s['genre'],'domains':['professional','public','educational'],'topics':[theme]+s['topics'],'text':text,'word_count':len(text.split()),'sentence_count':max(1,len(re.findall(r'[.!?](?:[»”\"])?',text))),'estimated_known_token_coverage':0,'new_lexical_targets':new,'review_lexical_targets':rev,'grammar_targets':[{'id':s['id']+'-g1','role':'integration','description':'integrate qualification, comparison, counterfactual and evidential scope'}],'discourse_targets':[{'id':s['id']+'-d1','role':'integration','description':'combine evidence, mechanism, values, competing interpretation, transfer and revision'}],'questions':q,'answer_key':a,'speed_training':{'timed':False,'benchmark_eligible':False,'comprehension_gate':0.8,'new_word_policy':'controlled','notes':'C1 Unit10 synthesis.'},'quality':{'status':'draft','schema_check':'pending','linguistic_review':'pending','pedagogical_review':'pending','answer_key_check':'pending','coverage_check':'pending','fact_check':'not_required','notes':['Cross-domain C1 synthesis with fictional cases.']},'paired_text_group':s.get('pair'),'prerequisites':['French C1 Unit09'],'difficulty_notes_internal':'C1 capstone synthesis across evidence, institutions, risk and interpretation.','reader_tags':['unit_role:integration','generation_batch','french_c1_u10']}
def specs():return [
 {'id':'fr-c1-u10-p01','seq':55,'title':'Synthétiser sans prétendre que toutes les preuves disent la même chose','genre':'multi-section essay','topics':['evidence synthesis','claim calibration'],'paras':["Un dossier fictif rassemble une enquête quantitative, des entretiens, un rapport professionnel et une critique méthodologique sur le même programme public. Les documents ne répondent pas exactement à la même question. La synthèse commence donc par cartographier les affirmations plutôt que compter combien de sources semblent favorables ou défavorables.","Les données quantitatives décrivent une variation moyenne; les entretiens éclairent des mécanismes possibles et des effets vécus; le rapport professionnel expose les contraintes d’implémentation. La critique méthodologique met en doute une hypothèse de sélection. Aucune source ne remplace les autres, car leurs objets et accès diffèrent.","Le contreargument soutient qu’une synthèse aussi nuancée ne produit jamais de conclusion. Le texte répond en hiérarchisant les affirmations : certaines sont convergentes, d’autres plausibles mais conditionnelles, et quelques-unes restent réellement ouvertes. La nuance devient une structure décisionnelle plutôt qu’une liste d’incertitudes.","La recommandation précise enfin ce qui peut être décidé maintenant et ce qui exige une nouvelle étude. Elle distingue une modification réversible du programme d’un engagement durable, puis associe chaque décision à un niveau de preuve proportionné."],'qclaim':'Quelle méthode organise la synthèse multi-source ?','aclaim':'Cartographier les affirmations et le type d’accès de chaque source avant de rechercher convergence, tension et décision.','qinfer':'Pourquoi compter les sources favorables est-il insuffisant ?','ainfer':'Parce que les sources peuvent mesurer des objets différents et ne pas être indépendantes ni comparables.','qassume':'Que suppose une hiérarchie d’affirmations utile ?','aassume':'Des critères explicites distinguant convergence, conditionnalité et questions encore ouvertes.','qrelation':'Comment le texte répond-il à l’objection d’une nuance paralysante ?','arelation':'Il relie différents niveaux de confiance à des décisions de portée et de réversibilité différentes.','astance':'Produire une conclusion graduée qui conserve la structure des preuves et permet d’agir proportionnellement.','asummary':'La synthèse combine des sources différentes en ajustant chaque affirmation à leur accès et chaque décision au niveau de preuve.'},
 {'id':'fr-c1-u10-p02','seq':56,'title':'Comprendre pourquoi une solution fonctionne avant de la transférer','genre':'multi-section essay','topics':['mechanism','transfer'],'paras':["Une organisation fictive souhaite copier un dispositif qui a réussi dans une autre région. Le rapport initial décrit une amélioration nette, mais la nouvelle région possède une structure de coûts, une population et des contraintes opérationnelles différentes. La question n’est pas seulement de savoir si le programme a réussi : il faut comprendre pourquoi.","La synthèse propose plusieurs mécanismes. L’effet peut venir d’une meilleure information, d’une incitation financière, d’une compétence rare ou d’une capacité inutilisée dans le site initial. Chacun de ces mécanismes prédit une réponse différente lorsque les conditions changent.","Le contreargument affirme qu’un test local suffit : il faut simplement essayer et observer. Le texte accepte la valeur d’un pilote, mais précise que son design doit distinguer les mécanismes importants; sinon un succès temporaire peut être attribué au mauvais facteur et mal guider l’expansion.","La recommandation combine théorie minimale et expérimentation. Elle identifie les conditions indispensables, choisit un pilote réversible, mesure les indicateurs qui départagent les mécanismes et annonce ce qui permettrait d’arrêter ou d’adapter le transfert."],'qclaim':'Pourquoi le succès initial ne suffit-il pas au transfert ?','aclaim':'Parce que les conditions causales peuvent différer; il faut identifier le mécanisme et tester s’il reste présent dans le nouveau contexte.','qinfer':'Quel est le risque d’un pilote sans hypothèses ?','ainfer':'Il peut réussir ou échouer sans révéler quel mécanisme explique le résultat, ce qui limite l’apprentissage.','qassume':'Que suppose un transfert raisonnable ?','aassume':'Au moins certaines conditions causales partagées et des mesures capables de détecter les différences importantes.','qrelation':'Comment le texte traite-t-il l’argument « essayons simplement » ?','arelation':'Il conserve l’expérimentation mais l’organise pour départager des mécanismes et maintenir une sortie réversible.','astance':'Transférer par mécanisme testable plutôt que par ressemblance superficielle.','asummary':'Comprendre ce qui produit l’effet permet de concevoir un pilote qui apprend réellement si la solution peut être transférée.'},
 {'id':'fr-c1-u10-p03','seq':57,'title':'Perspective A : une institution doit pouvoir répondre vite au dommage','genre':'paired perspectives','topics':['emergency response','institutional action'],'pair':PAIR,'paras':["Le premier point de vue examine une crise fictive où un service public détecte un dommage qui s’aggrave rapidement. Il soutient qu’une institution responsable ne peut pas attendre une certitude complète lorsque le délai augmente directement le coût humain ou matériel. Une réponse provisoire peut être justifiée par l’asymétrie des risques.","Cette position exige néanmoins un cadre. L’action rapide doit viser le mécanisme soupçonné, rester proportionnée et produire des informations qui permettent de vérifier si elle fonctionne. L’urgence n’autorise pas à confondre intuition et preuve.","Le contreargument redoute qu’une logique d’urgence rende toute restriction acceptable. Le point de vue A répond par des conditions de sortie : durée courte, réexamen indépendant, indicateurs observables et restauration des règles ordinaires lorsque la justification disparaît.","La conclusion défend donc une capacité d’intervention réversible. Une institution apprend en agissant, mais elle doit construire la correction dans la réponse initiale plutôt que promettre de l’ajouter plus tard."],'qclaim':'Quelle priorité défend le point de vue A ?','aclaim':'Permettre une réponse provisoire rapide lorsque le coût du délai est élevé, à condition qu’elle soit proportionnée, mesurable et réversible.','qinfer':'Pourquoi l’urgence ne suffit-elle pas comme justification ?','ainfer':'Parce qu’il faut encore relier l’action au mécanisme du dommage et prévoir comment vérifier son effet.','qassume':'Que suppose une intervention réversible ?','aassume':'Une durée, des indicateurs, une autorité de réexamen et une voie de retour explicites.','qrelation':'Comment le texte répond-il au risque d’abus de l’urgence ?','arelation':'Il limite l’action par des conditions de sortie, un contrôle indépendant et des critères observables.','astance':'Agir tôt lorsque le délai est coûteux tout en construisant la correction dans la mesure.','asummary':'L’urgence peut justifier une action provisoire, jamais l’abandon des critères, du contrôle et de la révision.'},
 {'id':'fr-c1-u10-p04','seq':58,'title':'Perspective B : une réponse robuste doit éviter de créer une seconde crise','genre':'paired perspectives','topics':['resilience','system effects'],'pair':PAIR,'paras':["Le second point de vue accepte parfois la nécessité d’agir vite, mais insiste sur les interactions du système. Une intervention qui résout un symptôme peut déplacer le risque vers un autre service, épuiser une ressource critique ou créer une dépendance difficile à inverser. La vitesse doit donc être accompagnée d’un test de robustesse.","Cette perspective examine les points de rupture et les dépendances. Elle demande quelles fonctions minimales doivent rester disponibles, quels groupes supportent l’effort supplémentaire et quelle solution de secours existe si la première intervention échoue.","Le contreargument affirme que cette prudence peut ralentir précisément la réponse urgente défendue par A. Le point de vue B répond qu’un contrôle de quelques dépendances critiques n’exige pas une analyse exhaustive; il vise les effets secondaires capables d’annuler le bénéfice initial.","La synthèse suggère une architecture commune : action provisoire, contrôle des dépendances critiques, mesure de l’effet, seuil d’arrêt et révision indépendante. Le désaccord porte davantage sur l’ordre et le poids des vérifications que sur la nécessité d’agir ou d’apprendre."],'qclaim':'Quelle priorité défend le point de vue B ?','aclaim':'Tester les dépendances et effets secondaires critiques afin qu’une réponse rapide ne crée pas une défaillance plus grave ailleurs.','qinfer':'Pourquoi une solution locale peut-elle être globalement mauvaise ?','ainfer':'Parce qu’elle peut déplacer ressources, risques ou dépendances vers une autre partie du système.','qassume':'Que suppose un test de robustesse rapide ?','aassume':'L’identification préalable de quelques fonctions ou dépendances dont la perte serait particulièrement coûteuse.','qrelation':'Comment le texte répond-il au risque de ralentissement ?','arelation':'Il limite le contrôle aux dépendances critiques plutôt qu’à une analyse exhaustive avant toute action.','astance':'Associer vitesse et robustesse par des contrôles ciblés des points de rupture.','asummary':'Une réponse rapide doit aussi protéger les fonctions dont la défaillance annulerait son bénéfice.','across':'A insiste sur le coût du délai et la réversibilité; B insiste sur les dépendances et effets secondaires. Les deux convergent vers une action provisoire mesurée, contrôlée et assortie d’un seuil de révision.'},
 {'id':'fr-c1-u10-p05','seq':59,'title':'Quand l’expertise conseille sans décider à la place du public','genre':'multi-section essay','topics':['expertise','professional judgment'],'paras':["Un comité fictif réunit des spécialistes de santé, de données, d’opérations et de sciences sociales pour examiner une politique. Le désaccord ne porte pas seulement sur les faits : certains membres accordent un poids différent à la prévention, au coût, à l’autonomie et à la distribution des effets.","La synthèse sépare expertise descriptive et choix normatif. Un professionnel peut estimer un risque ou expliquer un mécanisme dans son champ sans décider seul quel niveau de risque une institution doit accepter. Inversement, une préférence publique ne peut pas changer les propriétés mesurées d’un phénomène.","Le contreargument affirme que cette séparation est artificielle parce que les modèles incorporent déjà des choix. Le texte l’accepte partiellement : sélectionner un indicateur, une population ou un seuil peut avoir une dimension normative. La solution est de rendre ces choix visibles et de distinguer ceux qui peuvent être testés de ceux qui nécessitent une délibération.","La recommandation finale distribue les rôles : experts explicitent preuves, incertitudes et conséquences; décideurs justifient les valeurs et arbitrages; un mécanisme de suivi vérifie si les hypothèses centrales restent valables après mise en œuvre."],'qclaim':'Quelle séparation centrale organise le passage ?','aclaim':'Distinguer ce que l’expertise peut établir sur les faits et mécanismes de ce qui exige un choix explicite de valeurs ou de seuils.','qinfer':'Pourquoi un expert ne décide-t-il pas automatiquement du niveau de risque acceptable ?','ainfer':'Parce que l’acceptabilité implique des valeurs et arbitrages qui dépassent l’estimation technique du risque.','qassume':'Que suppose une délibération transparente ?','aassume':'Que les choix intégrés aux indicateurs et seuils soient rendus visibles et séparés des résultats empiriques lorsqu’il est possible de le faire.','qrelation':'Comment le texte traite-t-il l’objection selon laquelle les modèles contiennent déjà des valeurs ?','arelation':'Il l’admet en partie et propose d’identifier quels choix sont testables et lesquels nécessitent une justification normative.','astance':'Donner à l’expertise un rôle fort mais situé, associé à une justification publique des arbitrages.','asummary':'Les experts éclairent conséquences et incertitudes; la décision justifie séparément les valeurs et conserve un suivi révisable.'}]
def checkpoint(groups,deck,lo,hi,theme,prior):
 forms=[f for k in ['p01','p02','p03','p04','p05'] for f in groups[k]];ps=["Le checkpoint final C1 présente un dossier fictif qui combine une étude imparfaite, une décision professionnelle urgente, une règle institutionnelle, deux récits historiques contradictoires et un modèle de risque. La difficulté est volontairement cumulative : aucune discipline ne fournit seule la conclusion.","Le lecteur construit une matrice qui sépare faits, inférences, valeurs, horizons, acteurs et voies de révision. Il identifie également le meilleur argument contraire pour chaque recommandation, afin d’éviter qu’une seule source ou un seul cadre impose ses catégories à tout le problème.","La synthèse compare ensuite trois options. L’une maximise le bénéfice attendu mais dépend d’hypothèses fragiles; une autre protège mieux contre une perte grave mais coûte davantage; la troisième retarde l’action pour collecter plus d’information. Le choix dépend donc du coût du délai, de la réversibilité et de ce que la nouvelle information peut réellement changer.","La conclusion C1 ne cherche pas une certitude artificielle. Elle formule une recommandation actuelle, explique pourquoi elle est proportionnée aux preuves et aux valeurs annoncées, puis précise les observations qui obligeraient à la modifier. Le lecteur doit pouvoir reconstruire toute la chaîne plutôt que simplement accepter l’autorité du texte."];ps[1]+=' Révision cumulative : '+'; '.join(f'« {f} »' for f in forms)+'.';ps,text=fit(ps,lo,hi);P=base.prior(prior);rev=[base.rev(f,P) for f in forms];ids={t['form']:t['id'] for t in rev};items=[('main_claim','Quelle compétence globale le checkpoint évalue-t-il ?','Construire une recommandation C1 qui sépare faits, inférences, valeurs, risques et conditions de révision.',[forms[0]]),('inference','Pourquoi aucune discipline ne suffit-elle seule ?','Parce que les sources répondent à des dimensions différentes du problème et ont des limites d’accès distinctes.',[forms[1]]),('assumption','Que suppose une comparaison honnête des trois options ?','Des horizons, conséquences, coûts du délai et possibilités de révision explicitement comparables.',[forms[8]]),('argument_relation','Quel rôle joue le meilleur contreargument ?','Tester la fragilité de la recommandation et identifier l’information qui pourrait l’inverser.',[forms[12]]),('stance','Quelle posture finale caractérise le niveau C1 ?','Argumenter avec précision, intégrer des perspectives différentes et rester explicitement révisable.',[forms[16]]),('summary','Résume le checkpoint final.','Séparer les types d’affirmations, comparer les options et leurs erreurs possibles, justifier un choix actuel et annoncer ce qui le ferait changer.',[forms[19]]),('vocabulary_in_context',f'Quel rôle joue « {forms[3]} » ?',USE[forms[3]],[forms[3]]),('vocabulary_in_context',f'Quel rôle joue « {forms[10]} » ?',USE[forms[10]],[forms[10]]),('vocabulary_in_context',f'Quel rôle joue « {forms[14]} » ?',USE[forms[14]],[forms[14]]),('synthesis','Quelle règle C1 peut être transférée à un nouveau domaine ?','Adapter la force de la conclusion à la preuve, distinguer les valeurs, tester une alternative sérieuse et construire une voie de révision.',[forms[6],forms[18]])];q,a=base.qa(items,ids)
 return {'id':'fr-c1-u10-p06','language':'fr','cefr':'C1','unit':10,'sequence':60,'revision':1,'title':'Checkpoint C1 : argumenter, intégrer et réviser','passage_type':'checkpoint','genre':'checkpoint','domains':['professional','public','educational'],'topics':[theme,'C1 cumulative synthesis'],'text':text,'word_count':len(text.split()),'sentence_count':max(1,len(re.findall(r'[.!?](?:[»”\"])?',text))),'estimated_known_token_coverage':0,'new_lexical_targets':[],'review_lexical_targets':rev,'grammar_targets':[{'id':'fr-c1-u10-p06-g1','role':'integration','description':'integrate epistemic, normative, conditional and contrastive qualification'}],'discourse_targets':[{'id':'fr-c1-u10-p06-d1','role':'integration','description':'synthesize evidence, values, risk, counterargument, transfer and explicit revision'}],'questions':q,'answer_key':a,'speed_training':{'timed':True,'benchmark_eligible':True,'comprehension_gate':0.8,'new_word_policy':'none','notes':'C1 final zero-new checkpoint.'},'quality':{'status':'draft','schema_check':'pending','linguistic_review':'pending','pedagogical_review':'pending','answer_key_check':'pending','coverage_check':'pending','fact_check':'not_required','notes':['C1 cumulative checkpoint; final language-wide French audit remains deferred until C2.']},'paired_text_group':None,'prerequisites':['French C1 Units01-10 P01-P05'],'difficulty_notes_internal':'C1 cumulative capstone.','reader_tags':['unit_role:checkpoint','generation_batch','french_c1_u10']}
def main():
 raw=C1.read_text();rows=[json.loads(x) for x in raw.splitlines() if x.strip()];l=json.loads(LOCK.read_text());p=json.loads(PLAN.read_text());s=json.loads(SEL.read_text());c=h(C1);b=h(B2)
 if len(rows)!=54 or l.get('status')!='PASS' or l.get('c1_canonical_blob')!=c or l.get('b2_canonical_blob')!=b:raise AssertionError('Unit10 source mismatch')
 if p.get('c1_source_blob')!=c or s.get('c1_source_blob')!=c:raise AssertionError('Unit10 plan/selection stale')
 groups=s['passage_groups'];r=l['unit09_target_groups'];reviews={k:r[k] for k in ['p01','p02','p03','p04','p05']};deck=base.deck();lo,hi=s['word_band'];unit=[mk(x,groups[x['id'][-3:]],reviews[x['id'][-3:]],rows,deck,lo,hi,p['theme']) for x in specs()];unit.append(checkpoint(groups,deck,lo,hi,p['theme'],rows+unit));V=Draft202012Validator(json.loads(SCHEMA.read_text()))
 for x in unit:
  errs=sorted(V.iter_errors(x),key=lambda e:list(e.path))
  if errs:raise AssertionError(f"{x['id']}: schema {[e.message for e in errs[:8]]}")
 C1.write_text(raw.rstrip('\n')+'\n'+''.join(json.dumps(x,ensure_ascii=False,sort_keys=True)+'\n' for x in unit));print(json.dumps({'status':'PASS','c1_passages':60,'word_counts':{x['id']:x['word_count'] for x in unit}},ensure_ascii=False))
